/* Classic 12T, 12 MHz. Timer0 owned here; nominal timing plus software overhead. */
void wait_ms(u16 n) {
    TMOD = (TMOD & 0xF0) | 0x01;
    while (n--) {
        TR0=0; TH0=0xFC; TL0=0x18; TF0=0; TR0=1;
        while (!TF0) { }
        TR0=0; TF0=0;
    }
}
sbit LED=P1^0;
void main(void) { LED=1; for (;;) { LED=0; wait_ms(500); LED=1; wait_ms(500); } }

